import os, sys
from xml.dom import minidom

base = "quarterly_report_unpacked"
for root, dirs, files in os.walk(base):
    for f in files:
        print(os.path.join(root, f))

print("-----PARAGRAPH DUMP-----")
path = os.path.join(base, "word", "document.xml")
dom = minidom.parse(path)
ns = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
def ln(tag):
    return dom.getElementsByTagNameNS(ns, tag)

def node_text(el):
    parts = []
    for t in el.getElementsByTagNameNS(ns, "t"):
        parts.append(t.firstChild.nodeValue if t.firstChild else "")
    for dt in el.getElementsByTagNameNS(ns, "delText"):
        parts.append("[DEL:" + (dt.firstChild.nodeValue if dt.firstChild else "") + "]")
    return "".join(parts)

for i, p in enumerate(ln("p")):
    styles = p.getElementsByTagNameNS(ns, "pStyle")
    style = styles[0].getAttributeNS(ns, "val") if styles else ""
    text = node_text(p).strip()
    # underline info per run
    uls = []
    for r in p.getElementsByTagNameNS(ns, "r"):
        ups = r.getElementsByTagNameNS(ns, "u")
        if ups:
            uls.append(ups[0].getAttributeNS(ns, "val"))
    print(f"[{i}] style={style!r} text={text!r} underlines={uls}")

"""Underline all headlines in quarterly_report.docx (unpacked intermediate).

Headline identification: paragraphs whose text is non-empty, contains at least
one alphabetic character, and contains no lowercase characters (i.e. the
all-caps section-title lines such as "EXECUTIVE SUMMARY", "RISK FACTORS").
Body sentences contain lowercase and are excluded; bullet/table rows contain
lowercase and are excluded; the box-drawing separator line has no letters and
is excluded.
"""
import xml.dom.minidom as minidom

DOC = 'unpacked/word/document.xml'
NS = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'

with open(DOC, 'r', encoding='ascii') as fh:
    raw = fh.read()
first_nl = raw.index('\n')
decl = raw[:first_nl]

dom = minidom.parse(DOC)
doc_el = dom.documentElement


def para_text(p):
    parts = []
    for t in p.getElementsByTagNameNS(NS, 't'):
        if t.firstChild is not None:
            parts.append(t.firstChild.data)
    return ''.join(parts)


def is_headline(text):
    s = text.strip()
    if not s:
        return False
    if not any(ch.isalpha() for ch in s):
        return False
    return not any(ch.islower() for ch in s)


def add_underline(rpr):
    # Build <w:u w:val="single"/> and place it after sz/szCs (valid rPr order).
    frag = minidom.parseString(
        '<w:u xmlns:w="%s" w:val="single"/>' % NS
    )
    u = dom.importNode(frag.documentElement, True)
    anchor = None
    for child in rpr.childNodes:
        if child.nodeType == child.ELEMENT_NODE:
            name = child.localName or ''
            if name in ('szCs', 'sz', 'highlight', 'color', 'spacing', 'w',
                        'kern', 'position'):
                anchor = child
    if anchor is not None:
        rpr.insertBefore(u, anchor.nextSibling)
    else:
        rpr.appendChild(u)


headline_count = 0
run_count = 0
for p in doc_el.getElementsByTagNameNS(NS, 'p'):
    if not is_headline(para_text(p)):
        continue
    headline_count += 1
    for r in p.getElementsByTagNameNS(NS, 'r'):
        for rpr in r.getElementsByTagNameNS(NS, 'rPr'):
            already = any(
                (c.nodeType == c.ELEMENT_NODE and (c.localName == 'u'))
                for c in rpr.childNodes
            )
            if not already:
                add_underline(rpr)
                run_count += 1

print('headline paragraphs found:', headline_count)
print('runs underlined:', run_count)


class Writer(object):
    def __init__(self):
        self.parts = []

    def write(self, s):
        self.parts.append(s)


w = Writer()
doc_el.writexml(w)
out = decl + '\n' + ''.join(w.parts) + '\n'
data = out.encode('ascii', 'xmlcharrefreplace')
with open(DOC, 'wb') as fh:
    fh.write(data)
print('document.xml written')

