import os
import re
import sys

sys.path.insert(0, os.path.join(os.getcwd(), ".codex", "skills", "docx"))
from scripts.document import Document

UNPACKED = sys.argv[1] if len(sys.argv) > 1 else "unpacked_quarterly_report"

RPR_ORDER = {
    "rStyle": 0, "rFonts": 1, "b": 2, "bCs": 3, "i": 4, "iCs": 5,
    "caps": 6, "smallCaps": 7, "strike": 8, "dstrike": 9, "outline": 10,
    "shadow": 11, "emboss": 12, "imprint": 13, "noProof": 14,
    "snapToGrid": 15, "vanish": 16, "webHidden": 17, "color": 18,
    "spacing": 19, "w": 20, "kern": 21, "position": 22, "sz": 23,
    "szCs": 24, "highlight": 25, "u": 26, "effect": 27, "bdr": 28,
    "shd": 29, "fitText": 30, "vertAlign": 31, "rtl": 32, "cs": 33,
    "em": 34, "lang": 35, "eastAsianLayout": 36, "specVanish": 37,
    "oMath": 38,
}
U_RANK = RPR_ORDER["u"]


def tag(elem):
    return elem.tagName.rsplit("}", 1)[-1]


def para_text(p):
    return "".join(
        t.firstChild.data
        for t in p.getElementsByTagName("w:t")
        if t.firstChild
    )


def add_underline(rpr):
    new_u = rpr.ownerDocument.createElement("w:u")
    new_u.setAttribute("w:val", "single")
    kids = [n for n in rpr.childNodes if n.nodeType == n.ELEMENT_NODE]
    insert_after = -1
    for i, k in enumerate(kids):
        if RPR_ORDER.get(tag(k), 99) < U_RANK:
            insert_after = i
    if insert_after >= 0:
        rpr.insertBefore(new_u, kids[insert_after].nextSibling)
    else:
        rpr.appendChild(new_u)


def is_headline(p):
    text = para_text(p).strip()
    if not text or len(text) > 60:
        return False
    if text != text.upper():
        return False
    return any(c.isalpha() for c in text)


doc = Document(UNPACKED)
editor = doc["word/document.xml"]
headlines = []
for p in editor.dom.getElementsByTagName("w:p"):
    if not is_headline(p):
        continue
    for child in list(p.childNodes):
        if child.nodeType != child.ELEMENT_NODE or tag(child) != "w:r":
            continue
        rprs = [n for n in child.childNodes
                if n.nodeType == n.ELEMENT_NODE and tag(n) == "w:rPr"]
        if rprs:
            rpr = rprs[0]
        else:
            rpr = child.ownerDocument.createElement("w:rPr")
            child.insertBefore(rpr, child.firstChild)
        add_underline(rpr)
    headlines.append(para_text(p).strip())

print("Headlines underlined (%d):" % len(headlines))
for h in headlines:
    print(" - " + h)
doc.save()

